using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup so the .zip file and metrics are ready
var modelService = new TicketModelService(
    LoggerFactory.Create(b => b.AddConsole()).CreateLogger<TicketModelService>(),
    builder.Environment);
modelService.TrainAndSave();

builder.Services.AddSingleton(modelService);
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelService.ModelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

